Definition wcall_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  match t with
  | CC.TOther pc =>
      if Nat.eqb i JVAL then
        if Z.eqb pc SETEC then
          match CH2.ret_of G.RETS i k with
          | Some j => match nth_error G.CPS j with
                      | Some cj => PB.has cells (KRange UV 0 6) &&
                                 forallb (fun code => match setec_chk code c ps cj (nth i G.BLS []) (nth j G.BLS []) with
                                                      | Some _ => (ECODE j =? code) && SPTW.adm_all A1V cells 0 7 (fun u => negb (u =? 0) && (PMR.conv_errc u =? code))
                                                      | None => true end) CODES
                      | None => false end
          | None => false end
        else if Z.eqb pc PARENT then PB.has cells (KRange UV 0 0)
        else true
      else true
  | _ => true
  end%bool.
Lemma wcall_ok : CH2.leaves_all G.CPS G.TAGS wcall_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,L+^:,^;!3+[+^:!3'`P'^@'^A'a0,^;").
Qed.
(* [comment removed for export] *)
Definition werr_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  match t with
  | CC.TOther pc => negb (is_err i) || forallb (fun code => negb (PB.has cells (KWord (SA Eb 0) 4 (ELit code))) || (ECODE i =? code)) CODES
  | _ => true
  end%bool.
Lemma werr_ok : CH2.leaves_all G.CPS G.TAGS werr_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,L+^:,^;!3+[+^:!3'`P'^@'^A'a1,^;").
Qed.
