(* [comment removed for export] *)
Lemma exit_gen : forall g1 M0c, OKV M0c -> forall i c k ps1 pc stv morev sendv,
  is_leaf i c k ps1 (CC.TOther pc) -> PB.exit_base_chk GT.NF RETPC c ps1 = true -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true -> view_chk (SR.ps_cells ps1) stv morev sendv = true ->
  (forall E1 E' R' (M1 M' : mem) model1, env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XIv g1 i E1 M1 -> HAMBV g1 M0c i E1 M' model1 -> env_agree GT.NF E0 E' ->
      L5.defined M' E 16 -> (forall a, 0 <= a < hl_ceil L -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      exists (more' : bool) (stack' : list Z) (code : Z) (g' : PML.ls_state),
        uv E' morev = PML.b2z more' /\ L5.bytes_at RSEGS M' sb stack' /\ uv E' sendv = sb + Z.of_nat (length stack') /\ Z.of_nat (length stack') <= scap /\
        PML.ec_at M' E code /\ (code <> 0 -> more' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\
        forall buf, let ps' := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) level stack' sb scap bcap bptr buf (PML.ps_win ps) in
          PML.wf_ps ps' /\ PMX.key_inv ps' /\ PML.buf_need ps' = 0 /\
          ((code = 0 /\ more' = true /\ In (uv E' stv) [PML.ST_EXPECT_COLON; PML.ST_EXPECT_COMMA_OR_END; PML.ST_ACCEPT]) \/ In code [25; 26; 27; 28; 29]) /\
          (PMW.win_bytes M' ps' ww -> SPTW.w3x PMW.FEndStringValue cw txt M' P ps ps' ww eg g1 code)) ->
  CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros g1 M0c OKV0 i c k ps1 pc stv morev sendv IL Hchk HBL HVW PREM.
  intros fx' E1 R1 M1 m1 E' R' M' HAt [HAmb HX] HFP Hag HLF _.
  pose proof Hentry as (Hra & Hraok & _ & _ & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (kitx SPTX.okV_defc M0c OKV0) as DEFC.
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; first [apply CL5.ev_reg | exact (kit SPT.EV0 x) | exact (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb x)]).
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (gblocks_amb g1 M0c i E1 M1 m1 HAmb) as GB.
  apply (PB.exit_ret L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS K (XIv g1)
           (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) (fun _ => 0) (fun _ => 0)
           SCRC (proj2 S7) S6 DEFC R EV r Hra Hraok heap_ok3 RETPC i c k ps1 pc ret_at IL Hchk fx' E1 R1 M1 m1 E' R' M' HAt HAmb Hag HLF).
  intros HRP HP HA' HagE'.
  pose proof HA' as HA0. destruct HA' as (Hmo1 & Hbv1 & HagE1 & (cr1 & HH1 & HC1) & _ & _).
  pose proof (SPT.pa_def _ _ _ HPA) as HdP.
  pose proof HEC as (_ & HdE & _).
  assert (HdE' : L5.defined M' E 16).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 E 16 HA0 OKV0 HdE). left.
    pose proof OE as (OE1 & OE2 & _). split; [lia|]. lia. }
  assert (HdP' : L5.defined M' P 272).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 P 272 HA0 OKV0 HdP). left.
    pose proof OP as (OP1 & OP2 & _). split; [lia|]. lia. }
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as LOW.
  destruct (PREM E1 E' R' M1 M' m1 Hag HLF HX HA0 HagE' HdE' LOW)
    as (more' & stack' & code & g' & Hmv & Hstk & Hsv & Hsl & HEC2 & Hmore2 & HLS2 & Hg' & HPS).
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HKC.
  destruct (view_gen _ stv morev sendv E' M' more' stack' HVW HKC HagE' HdP' Hmv Hstk Hsv Hsl) as (buf & HPA2 & Hbl).
  destruct (HPS buf) as (HWF2 & HKI2 & HBN2 & HREL & HW3).
  pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV2 & HLIT2).
  pose proof (kitx SPTX.okV_hpres g1 M0c M' OKV0 HP) as HP2.
  set (ps2 := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) level stack' sb scap bcap bptr buf (PML.ps_win ps)) in *.
  assert (Hwin2 : PML.ps_win ps2 = PML.ps_win ps) by reflexivity.
  assert (HWB2 : PMW.win_bytes M' ps2 ww).
  { apply (SPTW.win_bytes_kept L HI HIok LAY (PML.ps_blocks ps ++ LBo ++ gB eg) cr M M' (m_vmmaps model) LBo sp SCRC W ps ps2 ww HH);
      [intros b0 Hb0; apply in_or_app; right; apply in_or_app; left; exact Hb0 | exact (proj1 HP2) | exact S6 | lia | lia | exact (SPTW.wparx_split L LAY sp P V E S2 OBJS) | exact HWIN | exact HWB | exact Hwin2]. }
  assert (HWIN2 : PML.win_ok M' LBo ps2).
  { unfold PML.win_ok in *. cbn [PML.ps_win ps2]. destruct (PML.ps_win ps) as [[p0 e0]|]; [|exact I].
    destruct HWIN as (ch & Hch & W1 & W2 & Wd). exists ch. split; [exact Hch|]. split; [exact W1|]. split; [exact W2|].
    apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 p0 (e0 - p0) HA0 OKV0 Wd). right. exists ch. split; [exact Hch|]. lia. }
  assert (HBB2 : PML.buf_bound ps2 B).
