Lemma leaf_vis : forall g1 M0c, OKV M0c -> forall (iskey : bool) c k ps1 j cj ci, is_leaf JPAR c k ps1 (CC.TOther (if iskey then VKEYPC else VSTR)) -> CH2.ret_of G.RETS JPAR k = Some j -> nth_error G.CPS j = Some cj ->
  SR.ps_pc ps1 = (if iskey then VKEYPC else VSTR) -> is_post j = true -> (if iskey then Nat.eqb j JVKEY else is_vret j) = true ->
  expr_eqb (nth 11 (CA.ps_reglist ps1) (ELit 0)) (APC.eaddz (EVar 2) SVOFF) = true -> PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) SVOFF) 8 SX) = true -> PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) (SVOFF + 8)) 8 LENX) = true ->
  (if iskey then SPW.eq_chk (SR.ps_cells ps1) ROT 8 else expr_eqb (nth 12 (CA.ps_reglist ps1) (ELit 0)) TAG) = true -> CH2.blocks_eqb (nth j G.BLS []) SPT.BL0 = true ->
  VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth JPAR G.BLS []) (nth j G.BLS []) = Some ci -> CH2.ci_csp ci <= SVOFF ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c JPAR c ps1.
Proof.
  intros g1 M0c OKV0 iskey c k ps1 j cj ci IL Hret Hcj Hpc Hpost Hj Hr11 HSX HLENX HTAG HBL Hvis Hcsp.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  assert (SV : SVOFF = -80) by reflexivity.
  assert (MN : PML.ST_MEMBER_NAME = 16) by reflexivity.
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof OBJS as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OS1 & OS2 & _) & (OE1 & OE2 & _) & _).
  assert (OBJSE : PMES.objs_enc L sp V S2) by (unfold PMES.objs_enc; unfold PMX.objs_x in OBJS; tauto).
  assert (Hcn : c = nth JPAR G.CPS G.cp0) by (symmetry; apply nth_error_nth; exact Hc).
  assert (GPV : APC.expr_vars_lt (CC.cp_nx (nth JPAR G.CPS G.cp0)) GP = true) by (vm_compute; reflexivity).
  rewrite <- Hcn in GPV.
  assert (HBLS : CH2.blocks_eqb (nth JPAR G.BLS []) SPT.BL0 = true) by (vm_compute; reflexivity).
  pose proof Htxtb as (Htb & Htl).
  pose proof (PMX.kenc_eq L eg) as KEQ.
  assert (HPC' : PML.pcredit_x L cr ps (kx + PMES.kenc L eg) (bxu + PMES.benc L eg)) by (rewrite <- KEQ, <- Hbxu; exact HPC).
  assert (Hscap : PML.ps_scap ps <= 1056).
  { destruct WFM as (_ & Hsc & _). unfold scap in Hsc. destruct Hsc as [Hs|[Hs|[Hs|[Hs|[Hs|[]]]]]]; lia. }
  assert (SITE0 : forall Ec R1 (M1 : mem) model1 E' R' (M' : mem) cr1, CC.At (hl_segs L) c Ec R1 M1 -> HAMBV g1 M0c JPAR Ec M1 model1 -> XIv g1 JPAR Ec M1 ->
            env_agree (CC.cp_nx c) Ec E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
            CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo eghost gB g1) sp G.HDECL W G.BLS (CredV g1) VBX.VIS_SCR 0 c ps1 cj ci JPAR Ec E' R' M' model1 ->
            CredV g1 JPAR Ec cr1 ->
            g1 = eg /\ env_agree GT.NF E0 E' /\ PML.a1 R' (sp + SVOFF) /\
            PMES.sv_argU L (CH2.den E' (nth JPAR G.BLS []) ++ LBo) M' (sp + CH2.ci_csp ci) V S2 (sp + SVOFF) txt /\
            PMES.enc_inv M' V S2 g1 /\ PML.img_ro M' /\ PML.lits_ok M' /\
            PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps) /\
            (exists rest x, PML.ps_stack ps = rest ++ [x] /\ PB.uv E' GP = x /\ In x [0; 8; 14; 16]) /\
            PMR.validate txt = 0 /\ know_ok RSEGS E' M' (SR.ps_cells ps1) /\
            getr R' 12%bv = edenot E' (nth 12 (CA.ps_reglist ps1) (ELit 0))).
  { intros Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HXI Hag HLF CF HC.
    pose proof CF as [HA' HR Hreq (CV1 & CV2 & CV3 & CV4 & CV5) HKc [Hra' Hraok'] (Hsp' & Hc1 & Hs0 & Hc2) Hstk' Htp' HagE' Hden Hmeas].
    pose proof HXI as HXI0. destruct HXI as (HXJ & (HINV1 & HLIT1) & HGF).
    assert (HX0 : XI0 M1) by (exact (xi0_of JPAR Ec M1 eq_refl HXJ)).
    assert (HLOW : XLOW M1) by (exact (xi_low JPAR Ec M1 eq_refl eq_refl HXJ)).
    unfold XIj in HXJ. cbv zeta in HXJ.
    assert (EJ : is_err JPAR = false) by reflexivity. assert (PJ : is_post JPAR = false) by reflexivity. assert (VJ : is_vret JPAR = false) by reflexivity.
    rewrite EJ, PJ in HXJ. destruct HXJ as ((_ & HXG) & _ & HW0).
    specialize (HXG (Nat.eqb_refl _)). specialize (HW0 (Nat.eqb_refl _)).
    unfold GF in HGF. rewrite VJ, PJ in HGF. subst g1.
    assert (HdenJ : CH2.den E' (nth JPAR G.BLS []) = PML.ps_blocks ps).
    { rewrite (CH2.blocks_eqb_eq _ _ HBLS). exact (kit SPT.den_BL0 E' HagE'). }
    pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HKC.
    pose proof (below_frame JPAR c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as LOW.
    destruct (FRZA E' HagE') as (USX & ULEN & UTAG).
    destruct (est_sv E' HagE') as (ES1 & ES2 & ES3).
    assert (ES3' : bv_unsigned (edenot E' (APC.eaddz (EVar 2) SVOFF)) = sp + SVOFF) by exact ES3.
    assert (R11 : nth 11 (CA.ps_reglist ps1) (ELit 0) = APC.eaddz (EVar 2) SVOFF) by (apply expr_eqb_eq; exact Hr11).
    assert (G11 : getr R' 11%bv = edenot E' (APC.eaddz (EVar 2) SVOFF)).
    { rewrite (HR 11%bv). unfold sr_get. change (bv_eqb (11%bv : bv 5) 0) with false. cbv iota. change (ridx 11%bv) with 11%nat. rewrite Hreq, R11. reflexivity. }
    assert (G12 : getr R' 12%bv = edenot E' (nth 12 (CA.ps_reglist ps1) (ELit 0))).
    { rewrite (HR 12%bv). unfold sr_get. change (bv_eqb (12%bv : bv 5) 0) with false. cbv iota. change (ridx 12%bv) with 12%nat. rewrite Hreq. reflexivity. }
    assert (HTB' : L5.bytes_at RSEGS M' s txt).
    { apply (kit SPT.bytes_below M1 M' s len txt); [exact LOW | lia | lia | lia | exact (xlow_txt M1 HLOW)]. }
    assert (HDF : L5.defined M' s len).
    { apply (L5C.defined_agree M M' s len); [|exact Htxt]. intros z Hz. rewrite (LOW z) by lia. rewrite (HLOW z) by lia. reflexivity. }
    assert (U1 : PML.u64 M' (sp + SVOFF) s).
    { pose proof (PB.has_ok E' M' _ _ HKC HSX) as K1. unfold PML.u64. eapply CL5.kword64_elim; [exact K1 | exact ES1 | exact USX]. }
    assert (U2'' : PML.u64 M' (sp + SVOFF + 8) len).
    { pose proof (PB.has_ok E' M' _ _ HKC HLENX) as K2. unfold PML.u64. eapply CL5.kword64_elim; [exact K2 | exact ES2 | exact ULEN]. }
    assert (HIMG : PML.img_ro M').
    { pose proof (proj1 HLS) as HIM. unfold PML.img_ro, L5.img_clear in *. intros a Ha.
      assert (Fa : 0 <= a < hl_ceil L) by (pose proof (foot_low a ltac:(unfold PB2.ls_foot; left; exact Ha)); lia).
      rewrite (LOW a Fa), (HLOW a Fa). exact (HIM a Ha). }
    destruct (xinv_leaf eg JPAR c Ec M1 M' E' R' ps1 Hc (gblocks_amb eg M0c JPAR Ec M1 model1 HAmb) HXI0 HagE' HLF) as (HINV' & HLIT').
    assert (AGP : PB.uv E' GP = PB.uv Ec GP) by (exact (PB.uv_agree (CC.cp_nx c) Ec E' GP Hag GPV)).
    destruct HXG as (rest & x & Hstk & HGPx).
    assert (Hx : In x [0; 8; 14; 16]).
    { destruct (LAST rest x Hstk) as [[Hx0 _]|[[Hx0 _]|[Hx0 _]]].
      - rewrite MN in Hx0. subst x. cbn. lia.
      - subst x. cbn. lia.
      - destruct Hx0 as [Hx0|Hx0]; subst x; cbn; lia. }
    split; [reflexivity|]. split; [exact HagE'|].
    split; [unfold PML.a1; rewrite G11, <- ES3'; symmetry; apply Z_to_bv_bv_unsigned|].
    split.
    { exists s. rewrite SV in *.
      split; [exact U1|]. split; [unfold hl_ceil in *; lia|].
      split; [unfold PMES.len; rewrite Htl; exact U2''|].
      split; [exact HTB'|]. split; [unfold PMES.len; rewrite Htl; exact HDF|].
      split; [rewrite HdenJ; unfold PMES.len; rewrite Htl; exact HBLK|].
      split; [unfold PML.apart; left; lia|]. split; [unfold PML.apart; left; lia|].
      unfold PML.obj_on_stack. split; [lia|]. split; [lia|].
      assert (Hk : exists kk, sp = 16 * kk) by (exists (sp / 16); pose proof (Z.div_mod sp 16 ltac:(lia)); lia).
      destruct Hk as (kk & Hkk). rewrite Hkk. replace (16 * kk + -80) with ((2 * kk - 10) * 8) by ring. apply Z.mod_mul. lia. }
    split; [exact HINV'|]. split; [exact HIMG|]. split; [exact HLIT'|].
    split; [apply (SPXWU.ecredit_of_pxU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr1 ps eg kx bxu); [unfold CredV in HC; rewrite <- KEQ; exact HC | exact Hkx | exact Hbxu0 | exact Hscap]|].
    split; [exists rest, x; split; [exact Hstk|]; split; [rewrite AGP; exact HGPx | exact Hx]|].
    split; [exact HW0|]. split; [exact HKC | exact G12]. }
  assert (RET0 : forall Ec E' R' (M1 M' : mem) E2 (M2 : mem) g' cr', XIv g1 JPAR Ec M1 -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) Ec E' ->
            CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree (CH2.ci_nx ci) E' E2 -> (CC.cp_nx c <= CH2.ci_nx ci)%nat ->
            L5C.hpres L (CH2.den E' (nth JPAR G.BLS []) ++ LBo) (sp + CH2.ci_csp ci) VBX.VIS_SCR (W_enc V S2) M' M2 ->
            PMES.enc_inv M2 V S2 g' -> PML.lits_ok M2 -> PMES.ecreditU L cr' g' (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps) ->
            g1 = eg /\ XI0 M2 /\ XIG E2 /\ W0 /\ SPTX.xinv V S2 M2 g' /\ CredV g' j E2 cr').
  { intros Ec E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HP HINV2 HLIT2 HCR.
    destruct HXI as (HXJ & _ & HGF).
    assert (HX0 : XI0 M1) by (exact (xi0_of JPAR Ec M1 eq_refl HXJ)).
    unfold XIj in HXJ. cbv zeta in HXJ.
    assert (EJ : is_err JPAR = false) by reflexivity. assert (PJ : is_post JPAR = false) by reflexivity. assert (VJ : is_vret JPAR = false) by reflexivity.
    rewrite EJ, PJ in HXJ. destruct HXJ as ((_ & HXG) & _ & HW0).
    specialize (HXG (Nat.eqb_refl _)). specialize (HW0 (Nat.eqb_refl _)).
    unfold GF in HGF. rewrite VJ, PJ in HGF. subst g1.
    split; [reflexivity|].
    split.
    { pose proof (xi0_low M1 M' (below_frame JPAR c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) HX0) as (HF' & HB').
      destruct (stack_exprs E' HagE') as (_ & _ & (SL1 & SL2) & SC1 & SC2).
      destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & _).
      destruct (Hwf (sb, scap)) as ((B0 & B1 & B2 & B3 & B4) & _); [apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto|].
      cbn [fst snd] in B0, B1, B2, B3, B4. rewrite ILO, IHI in B1.
      assert (HdenJ : CH2.den E' (nth JPAR G.BLS []) = PML.ps_blocks ps).
      { rewrite (CH2.blocks_eqb_eq _ _ HBLS). exact (kit SPT.den_BL0 E' HagE'). }
      unfold slen in SL2.
      split.
      - intros a Ha. rewrite <- (HF' a Ha). apply (L5C.hpres_kept _ _ _ _ _ _ _ a HP).
        pose proof (foot_low a Ha) as Fa.
        split; [lia|]. split; [|split].
        + right. right. rewrite ILO, IHI. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. split; [lia|]. intros X. pose proof (PmLayout.ly_static L LAY a X). lia.
        + unfold in_errno. rewrite LER. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. lia.
        + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha.
          destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH in *; lia.
      - apply (L5C.bytes_at_agree RSEGS M' M2 sb (PML.ps_stack ps)); [| lia | lia | exact HB'].
        intros q Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
        split; [lia|]. split; [|split].
        + left. exists (sb, scap). split; [rewrite HdenJ; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; lia].
        + unfold in_errno. rewrite LER. lia.
        + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
          destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia. }
    split.
    { destruct HXG as (rest & x & Hr & Hx). exists rest, x. split; [exact Hr|].
      rewrite (PB.uv_agree (CC.cp_nx c) E' E2 GP (CC.env_agree_le _ _ _ _ Hag2 Hnx) GPV).
      rewrite (PB.uv_agree (CC.cp_nx c) Ec E' GP Hag GPV). exact Hx. }
    split; [exact HW0|]. split; [exact (conj HINV2 HLIT2)|].
    unfold CredV. rewrite (PMX.kenc_eq L g').
    apply (SPXWU.px_of_ecreditU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr cr' ps eg g' kx bxu); [exact HPC' | exact Hkx | exact Hbxu0 | exact HCR]. }
  destruct iskey.
  - apply Nat.eqb_eq in Hj. subst j.
    apply (VBXU.vis_leaf_ok_svU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
             G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) (proj2 (proj2 (proj2 (kit SPT.UU)))) S2LT
             (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
             VKEYPC (PMES.EvKey txt) txt (fun _ => True) (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
             JPAR c k ps1 JVKEY cj ci g1 M0c (VKEY txt) OBJSE OKV0 IL Hret Hcj Hpc Hvis).
    + intros Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HXI Hag HLF CF HH1 HC.
      destruct (SITE0 Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HXI Hag HLF CF HC)
        as (Hg1 & HagE' & Ha1' & HSV & HINV1 & HIMG & HLIT1 & HEC1 & (rest & x & Hstk & HGPx & Hx) & HW0 & HKC & _).
      subst g1.
      assert (HROT : PB.uv E' ROT = 8) by (exact (SPW.eq_chk_sound E' M' _ ROT 8 HKC HTAG ltac:(lia))).
      pose proof (rot_val E' x HGPx Hx) as HRV. rewrite HROT in HRV.
      assert (X16 : x = 16) by (destruct Hx as [<-|[<-|[<-|[<-|[]]]]]; cbn in HRV; first [reflexivity | lia]).
      assert (Hstk' : PML.ps_stack ps = rest ++ [PML.ST_MEMBER_NAME]) by (rewrite Hstk, X16, MN; reflexivity).
      split; [exists (sp + SVOFF); split; [exact Ha1'|]; split; [exact I | exact HSV]|].
      split; [exact HINV1|].
      split.
      { cbn [PMES.ev_guard]. intros Hn. pose proof (HKEY rest Hstk') as HL1. destruct HSYNC as (HD & _).
        unfold PMES.depth in HD. rewrite Hn in HD. cbn in HD. lia. }
      split; [exact (SPXWU.room_esv_key cw txt ps rest eg HRM HW0 Hstk' HROOM)|].
      split; [exact HIMG|]. split; [exact HLIT1 | exact HEC1].
    + intros Ec E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HP _ _ HRET HCR.
      destruct HRET as (HINV2 & HLIT2 & HES & HPAY).
      destruct (RET0 Ec E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HP HINV2 HLIT2 HCR) as (Hg1 & HX0 & HXG & HW0 & HXI2 & HCV).
      subst g1. split; [|exact HCV].
      split; [|split; [exact HXI2|]].
      * unfold XIj. cbv zeta. assert (E9 : is_err JVKEY = false) by reflexivity. assert (P9 : is_post JVKEY = true) by reflexivity.
        rewrite E9, P9. split; [split; [exact HX0 | exact HXG] | exact HW0].
      * unfold GF. assert (V9 : is_vret JVKEY = false) by reflexivity. assert (P9 : is_post JVKEY = true) by reflexivity.
        rewrite V9, P9. unfold GQ. cbv zeta. split; [exact HES | exact HPAY].
  - assert (Herr : is_err j = false).
    { pose proof Hj as Hj2. unfold is_vret in Hj2. apply existsb_exists in Hj2. destruct Hj2 as (rr & Hin & Hrr).
      destruct rr as [[[j' x1] x2] pp]. apply andb_prop in Hrr as [Hj' Hp]. apply Nat.eqb_eq in Hj'. subst j'.
      clear - Hin Hp. vm_compute in Hin.
      repeat (destruct Hin as [Hin|Hin]; [injection Hin; intros; subst; first [vm_compute; reflexivity | vm_compute in Hp; discriminate Hp]|]). destruct Hin. }
    assert (PGP : CH2.leaves_all G.CPS G.TAGS (fun i c0 k0 ps0 t => match t with
               | CC.TOther pc => (negb (Z.eqb pc VSTR) || EEK.pred_chk 70 (SR.ps_cells ps0) (fun x => negb (Z.eqb x 16)))%bool
               | _ => true end) = true) by (vm_compute; reflexivity).
    pose proof (CH2.leaves_all_sound _ _ _ PGP _ _ _ _ _ IL) as XP. cbv beta iota in XP. rewrite Z.eqb_refl in XP. cbn [negb orb] in XP.
    apply (VBXU.vis_leaf_ok_svU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
             G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) (proj2 (proj2 (proj2 (kit SPT.UU)))) S2LT
             (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
             VSTR (PMES.EvStr tag0 txt) txt (fun R0 => PML.a2 R0 tag0) (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
             JPAR c k ps1 j cj ci g1 M0c (VSTRING tag0 txt ltac:(lia)) OBJSE OKV0 IL Hret Hcj Hpc Hvis).
    + intros Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HXI Hag HLF CF HH1 HC.
      destruct (SITE0 Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HXI Hag HLF CF HC)
        as (Hg1 & HagE' & Ha1' & HSV & HINV1 & HIMG & HLIT1 & HEC1 & (rest & x & Hstk & HGPx & Hx) & HW0 & HKC & G12).
      subst g1.
      assert (HGPe : ev E' 70 = Z_to_bv 64 (PB.uv E' GP)) by (exact (PB.edenot_of_uv E' GP (PB.uv E' GP) eq_refl)).
      pose proof (EEK.pred_chk_sound RSEGS 70 _ _ E' M' (PB.uv E' GP) HKC HGPe ltac:(destruct Hx as [<-|[<-|[<-|[<-|[]]]]]; rewrite HGPx; lia) XP) as HN.
      cbv beta in HN. rewrite HGPx in HN.
      assert (Htop : x = PML.ST_OBJECT \/ x = PML.ST_ARRAY \/ x = PML.ST_ROOT).
      { destruct Hx as [<-|[<-|[<-|[<-|[]]]]]; vm_compute; first [left; reflexivity | right; left; reflexivity | right; right; reflexivity | vm_compute in HN; discriminate HN]. }
      destruct (FRZA E' HagE') as (_ & _ & UTAG).
      assert (R12 : nth 12 (CA.ps_reglist ps1) (ELit 0) = TAG) by (apply expr_eqb_eq; exact HTAG).
      split.
      { exists (sp + SVOFF). split; [exact Ha1'|]. split; [|exact HSV].
        unfold PML.a2. rewrite G12, R12. rewrite <- UTAG. symmetry. apply Z_to_bv_bv_unsigned. }
      split; [exact HINV1|]. split; [exact I|].
      split; [exact (SPXWU.room_esv_value cw txt ps rest x eg tag0 HRM HW0 Hstk Htop Htag01 HROOM)|].
      split; [exact HIMG|]. split; [exact HLIT1 | exact HEC1].
    + intros Ec E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HP _ _ HRET HCR.
      destruct HRET as (HINV2 & HLIT2 & HES & HPAY).
      destruct (RET0 Ec E' R' M1 M' E2 M2 g' cr' HXI HagE' Hag HLF Hag2 Hnx HP HINV2 HLIT2 HCR) as (Hg1 & HX0 & HXG & HW0 & HXI2 & HCV).
      subst g1. split; [|exact HCV].
      split; [|split; [exact HXI2|]].
      * unfold XIj. cbv zeta. rewrite Herr, Hpost. split; [split; [exact HX0 | exact HXG] | exact HW0].
      * unfold GF. rewrite Hj. unfold GQ. cbv zeta. split; [exact HES | exact HPAY].
Qed.

(* [comment removed for export] *)
Lemma leaf_exit_ok : forall i c k ps1 pc stz sendv rv, is_leaf i c k ps1 (CC.TOther pc) -> is_post i = true -> is_err i = false ->
  PB.exit_base_chk GT.NF RETPC c ps1 = true -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true ->
  PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true -> view_chk (SR.ps_cells ps1) (ELit stz) (ELit 1) sendv = true -> SPW.eq_chk (SR.ps_cells ps1) ROT rv = true ->
