Section Final.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis VALIDATE_OKW : PMW.validate_specw L PMR.the_rm.
Hypothesis PARENT_OK : PMS.parent_spec L.
Hypothesis POP_OK : PMS.pop_state_spec L.
Hypothesis SETEC_OK : PMS.set_ec_spec L.
Hypothesis VKEY : PMES.visit_key_specU L HI PMES.WD_SCR_X.
Hypothesis VSTRING : PMES.visit_string_specU L HI PMES.WD_SCR_X.

Theorem end_string_value_okw : PMW.end_string_value_specwU L HI PMES.WD_SCR_X PMR.the_rm.
Proof.
  unfold PMW.end_string_value_specwU, PMW.ptrans_stalexlwU, PMW.ptrans_gbxlwU. intros mw LBo cr sp r P V E S2 B kx bx g ps eg w x c. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp
    (Hentry & (Ha0 & Ha3 & Ha4 & Hmore & Hst & (t & Ht & Ht01) & (s & len & Ha1 & Ha2 & Hlen & Htxt & Hs1 & Hs2 & HBLK & Hbs & Hlx & HxF)) &
     HPA & HWF & HWIN & HBB & HVIS & HEC & HLS & HG & HINV & HLIT & HSYNC & Hkx & Hbx & HPC & OBJS & HWBY & HRM & HROOM) Hcont.
  pose proof (SPT.pa_def _ _ _ HPA) as HdP.
  destruct (PB2.cell_exists M (P + 160) 8 ltac:(lia)) as (line0 & Rl & Hl); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  destruct (PB2.cell_exists M (P + 168) 8 ltac:(lia)) as (pos0 & Rp & Hp); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  pose proof (PMX.key_ok_of_inv ps (proj2 HSYNC) Hmore) as HKEY.
  assert (Ht2 : 0 <= t < 256) by lia.
  exact (main L HI HIok LAY FPM VALIDATE_OKW PARENT_OK POP_OK SETEC_OK VKEY VSTRING mw LBo cr sp r P V E S2 B kx (bx + PMES.benc L eg) g ps eg fx R M model K s len
            HH Hmo HKnil Hfp Hentry Ha0 Ha1 Ha2 Ha3 Ha4 Hmore Hst Hlen Htxt (conj Hs1 Hs2) HKEY HBLK HPA HWF HWIN HBB HVIS HEC HLS HG HINV HLIT HSYNC Hkx HPC
            bx eq_refl Hbx OBJS w c HWBY HRM x (conj Hbs Hlx) HROOM HxF Hcont line0 pos0 t Hl Hp Ht (conj Rl (conj Rp Ht2)) Ht01).
Qed.

End Final.
End EndStringValueProofU.
